package com.codepilot1c.core.diagnostics;
import static org.junit.Assert.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import com.google.gson.*;

public class DiagnosticStandardsTest {
    static final String CODE="bslls:usingmodalwindows";
    static DiagnosticStandards.Entry entry(){return new DiagnosticStandards.Entry("resolved","Modal windows","https://v8std.ru/diagnostics/bslls/UsingModalWindows/",List.of(Map.of("id","std703","url","https://v8std.ru/std/703/#1","title","Modal windows","description","Use asynchronous operations","description_scope","article_intro")));}
    static DiagnosticStandards service(Path p,DiagnosticStandards.Resolver resolver,AtomicLong time){return new DiagnosticStandards(p,resolver,Runnable::run,time::get);}
    @SuppressWarnings("unchecked") static List<Map<String,Object>> items(Map<String,Object> m){return (List<Map<String,Object>>)m.get("items");}
    static String state(Map<String,Object> m){return (String)items(m).get(0).get("state");}
    @Test public void strictNamespacesNeverGuessFromMessage(){assertEquals("acc:361",DiagnosticStandards.canonical("АПК:361"));assertEquals(CODE,DiagnosticStandards.canonical("BSLLS:UsingModalWindows"));assertNull(DiagnosticStandards.canonical("361"));assertNull(DiagnosticStandards.canonical("bslls:foo\nprivate"));assertNull(DiagnosticStandards.code(Map.of("message",CODE)));assertNull(DiagnosticStandards.code(Map.of("check_id","UsingModalWindows","diagnostic_source","edt")));assertEquals(CODE,DiagnosticStandards.code(Map.of("code","UsingModalWindows","diagnostic_source","bslls")));}
    @Test public void exactCodesAreDeduplicatedAndCacheSurvivesRestart()throws Exception {Path p=Files.createTempDirectory("std-test");AtomicInteger calls=new AtomicInteger();AtomicLong time=new AtomicLong(1000);var s=service(p,c->{calls.incrementAndGet();assertEquals(List.of(CODE),c);return Map.of(CODE,entry());},time);var r=s.lookup(List.of(CODE,CODE),true);assertEquals("resolved",state(r));assertEquals(2,items(r).size());assertEquals(1,((Collection<?>)r.get("standards")).size());var restored=service(p,c->{fail("Fresh disk cache must avoid network");return Map.of();},time);assertEquals("resolved",state(restored.lookup(List.of(CODE),true)));assertEquals(1,calls.get());}
    @Test public void missingAndUnsupportedAreNotUnknownCodes()throws Exception {var s=service(Files.createTempDirectory("std-test"),c->{fail("No ID must not leave process");return Map.of();},new AtomicLong(1000));var r=s.annotate(List.of(Map.of("message","secret"),Map.of("check_id","unqualified-edt-id")),false);assertEquals("missing_id",items(r).get(0).get("state"));assertEquals("unsupported_source",items(r).get(1).get("state"));}
    @Test public void unavailableDoesNotEraseOriginalRowsAndUsesBackoff()throws Exception {AtomicInteger calls=new AtomicInteger();var row=new LinkedHashMap<String,Object>(Map.of("check_id",CODE,"message","PRIVATE","path","PRIVATE","severity",2));var original=new LinkedHashMap<>(row);var s=service(Files.createTempDirectory("std-test"),c->{calls.incrementAndGet();assertEquals(List.of(CODE),c);throw new java.io.IOException("secret transport error");},new AtomicLong(1000));var r=s.annotate(List.of(row),true);assertEquals("unavailable",state(r));assertEquals(original,row);assertFalse(new Gson().toJson(r).contains("PRIVATE"));assertFalse(new Gson().toJson(r).contains("secret transport"));s.annotate(List.of(row),true);assertEquals(1,calls.get());}
    @Test public void unknownIsNegativeCachedAndNotResolved()throws Exception {AtomicInteger calls=new AtomicInteger();AtomicLong time=new AtomicLong(1000);var s=service(Files.createTempDirectory("std-test"),c->{calls.incrementAndGet();return Map.of(CODE,new DiagnosticStandards.Entry("unknown_code","","",List.of()));},time);assertEquals("unknown_code",state(s.lookup(List.of(CODE),true)));s.lookup(List.of(CODE),true);assertEquals(1,calls.get());time.addAndGet(86400001);s.lookup(List.of(CODE),true);assertEquals(2,calls.get());}
    @Test public void staleCacheRetainsEvidenceOnOfflineRefresh()throws Exception {Path p=Files.createTempDirectory("std-test");AtomicLong t=new AtomicLong(1000);service(p,c->Map.of(CODE,entry()),t).lookup(List.of(CODE),true);t.addAndGet(604800001);var offline=service(p,c->{throw new java.io.IOException();},t);var r=offline.lookup(List.of(CODE),true);assertEquals("stale_cache",state(r));assertEquals("resolved",items(r).get(0).get("cached_state"));assertEquals(1,((Collection<?>)r.get("standards")).size());}
    @Test public void malformedCacheDoesNotBreakDiagnostics()throws Exception {Path p=Files.createTempDirectory("std-test");Files.writeString(p.resolve("cache-v1.json"),"{bad");var s=service(p,c->{throw new java.io.IOException();},new AtomicLong(1000));assertEquals("unavailable",state(s.lookup(List.of(CODE),true)));}
    @Test public void asyncEnrichmentReturnsWithoutWaitingAndCoalesces()throws Exception {AtomicInteger calls=new AtomicInteger();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService executor=Executors.newSingleThreadExecutor();try{var s=new DiagnosticStandards(Files.createTempDirectory("std-test"),c->{calls.incrementAndGet();entered.countDown();release.await();return Map.of(CODE,entry());},executor,()->1000);var r=s.lookup(List.of(CODE),false);assertTrue(entered.await(3,TimeUnit.SECONDS));assertEquals("lookup_pending",state(r));assertTrue(r.containsKey("next_call"));s.lookup(List.of(CODE),false);release.countDown();assertEquals("resolved",state(s.lookup(List.of(CODE),true)));assertEquals(1,calls.get());}finally{release.countDown();executor.shutdownNow();}}
    @Test public void invalidInputsNeverReachResolver()throws Exception {var s=service(Files.createTempDirectory("std-test"),c->{fail();return Map.of();},new AtomicLong(1000));for(var codes:List.of(List.of("UsingModalWindows"),List.of("bslls:code secret"),Collections.nCopies(101,CODE),List.<String>of()))try{s.lookup(codes,true);fail();}catch(IllegalArgumentException expected){}}
    @Test public void incompleteReplyIsUnavailableNotUnknown()throws Exception {var s=service(Files.createTempDirectory("std-test"),c->Map.of(),new AtomicLong(1000));assertEquals("unavailable",state(s.lookup(List.of(CODE),true)));}
    static String envelope(JsonObject data){JsonObject root=new JsonObject(),result=new JsonObject();result.add("structuredContent",data);root.add("result",result);return root.toString();}
    static JsonObject response(){JsonObject data=new JsonObject();JsonArray ds=new JsonArray();JsonObject diagnostic=new JsonObject();diagnostic.addProperty("id",CODE);diagnostic.addProperty("title","Modal");diagnostic.addProperty("url","https://v8std.ru/diagnostics/bslls/UsingModalWindows/");JsonArray links=new JsonArray();links.add(new Gson().toJsonTree(Map.of("id","std703","url","https://v8std.ru/std/703/#1","title","Modal","description","Rule")));diagnostic.add("standards",links);ds.add(diagnostic);data.add("diagnostics",ds);data.add("unknown_codes",new JsonArray());return data;}
    @Test public void decoderPreservesExplicitLinksAndSummary(){var result=V8StdClient.decode(envelope(response()),List.of(CODE));assertEquals("resolved",result.get(CODE).state());assertEquals("Rule",result.get(CODE).standards().get(0).get("description"));}
    @Test public void decoderRejectsHostileUrlsAndMismatchedCodes(){for(String value:List.of("https://attacker.invalid/std/703/","https://v8std.ru@attacker.invalid/","http://v8std.ru/std/703/")){var data=response();data.getAsJsonArray("diagnostics").get(0).getAsJsonObject().addProperty("url",value);try{V8StdClient.decode(envelope(data),List.of(CODE));fail();}catch(IllegalArgumentException expected){}}try{V8StdClient.decode(envelope(response()),List.of("acc:361"));fail();}catch(IllegalArgumentException expected){}}
    @Test public void decoderRejectsPartialUnknownAndToolError(){try{V8StdClient.decode(envelope(response()),List.of(CODE,"acc:361"));fail();}catch(IllegalArgumentException expected){}try{V8StdClient.decode("{\"result\":{\"isError\":true}}",List.of(CODE));fail();}catch(IllegalArgumentException expected){}}
    @Test public void cacheCannotRedirectNetworkOrSmuggleStandards()throws Exception {Path p=Files.createTempDirectory("std-test");var s=service(p,c->Map.of(CODE,new DiagnosticStandards.Entry("resolved","test","https://evil.invalid/",List.of())),new AtomicLong(1000));assertEquals("unavailable",state(s.lookup(List.of(CODE),true)));assertFalse(Files.exists(p.resolve("cache-v1.json")));}

    @Test public void serverNormalizedUnknownIdMapsBackToOriginal(){var data=new JsonObject();data.add("diagnostics",new JsonArray());var unknown=new JsonArray();unknown.add(new Gson().toJsonTree(Map.of("code","bslls:notreal")));data.add("unknown_codes",unknown);var result=V8StdClient.decode(envelope(data),List.of("bslls:NotReal"));assertEquals("unknown_code",result.get("bslls:NotReal").state());}
    @Test public void nativeContributorMustBeUniqueAndVerified(){var map=DiagnosticStandards.contributorCodes(Map.of("empty-except-statement",Set.of("com.e1c.v8codestyle.bsl"),"ambiguous",Set.of("com.e1c.v8codestyle.bsl","other.checker"),"core",Set.of("com._1c.edt")));assertEquals(Map.of("empty-except-statement","v8cs:empty-except-statement"),map);}
    @Test public void largeDiagnosticListsHaveBoundedAdvisoryView()throws Exception {var s=service(Files.createTempDirectory("std-test"),c->Map.of(CODE,entry()),new AtomicLong(1000));var rows=new ArrayList<Map<String,?>>();for(int i=0;i<500;i++)rows.add(Map.of("diagnostic_code",CODE));var r=s.annotate(rows,false);assertEquals(100,items(r).size());assertEquals(500,r.get("input_count"));assertEquals(true,r.get("items_truncated"));}

    @Test public void aDifferentPendingBatchNeverStrandsNextCodes()throws Exception {CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService executor=Executors.newSingleThreadExecutor();AtomicInteger calls=new AtomicInteger();try{var s=new DiagnosticStandards(Files.createTempDirectory("std-test"),c->{if(calls.incrementAndGet()==1){entered.countDown();release.await();}return Map.of(c.get(0),new DiagnosticStandards.Entry("unknown_code","","",List.of()));},executor,()->1000);s.lookup(List.of("acc:1"),false);assertTrue(entered.await(2,TimeUnit.SECONDS));release.countDown();var r=s.lookup(List.of("acc:2"),true);assertTrue("Unknown must be resolved or have an actionable continuation",state(r).equals("unknown_code")||r.containsKey("next_call"));assertEquals("unknown_code",state(s.lookup(List.of("acc:2"),true)));assertEquals(2,calls.get());}finally{release.countDown();executor.shutdownNow();}}
    @Test public void offlineModeDoesNotSendIdentifiers()throws Exception {String before=System.getProperty("codepilot.v8std.offline");try{System.setProperty("codepilot.v8std.offline","true");var s=service(Files.createTempDirectory("std-test"),c->{fail("Offline must not resolve");return Map.of();},new AtomicLong(1000));assertEquals("offline",state(s.lookup(List.of(CODE),true)));}finally{if(before==null)System.clearProperty("codepilot.v8std.offline");else System.setProperty("codepilot.v8std.offline",before);}}
}
